"""Exact actual-Java observer capture of authored OOXML; not original gold."""
import base64
import json
import zlib

AUTHORED_CAPTURE = ''


def fixture_bytes():
    raw = json.loads(zlib.decompress(base64.b64decode(AUTHORED_CAPTURE)))
    return tuple(base64.b64decode(raw[name]) for name in ('export', 'source', 'adapter'))
